/// <summary>
///     AVA <c>createSalesLineTmpTableRecord</c> method.
///     Initializes the default data in the template record.
///     AVA - Schneider 13.02.2024
/// </summary>
protected void initWMSPickingList_OrderPickTmpTemplate()
{
    clsWMSPickingRouteID = wmsPickingRoute.PickingRouteID;

    // generate empty barcode string to avoid error in validation process in this.barcode()
    wmsPickingRoute.PickingRouteID = '';

    next initWMSPickingList_OrderPickTmpTemplate();

    // reassign picking route id and missing values
    wmsPickingRoute.PickingRouteID                      = clsWMSPickingRouteID;
    wmsPickingList_OrderPickTmpTemplate.PickingRouteID  = wmsPickingRoute.PickingRouteID;
}
